def __mode_from_size_segment(size_segment):
    if size_segment == 'full':
        return FULL_MODE
    if SizeParameter.PCT_MODE_REGEX.match(size_segment):
        return PCT_MODE
    m = SizeParameter.PIXEL_MODE_REGEX.match(size_segment)
    if m is not None:
        if m.group('best_fit') and m.group('width') and m.group('height') or (not m.group('best_fit') and (m.group('width') or m.group('height'))):
            return PIXEL_MODE
    message = 'Size syntax %r is not valid' % size_segment
    raise SyntaxException(http_status=400, message=message)

processed_final_repaired_code:
def __mode_from_size_segment(size_segment):
    if size_segment.startswith('pct:'):
        return PCT_MODE
    elif size_segment == 'full':
        return FULL_MODE
    elif ',' not in size_segment:
        msg = 'Size syntax "%s" is not valid' % (size_segment,)
        raise SyntaxException(http_status=400, message=msg)
    elif all((n.isdigit() for n in size_segment.split(','))):
        return PIXEL_MODE
    else:
        msg = 'Size syntax "%s" is not valid' % (size_segment,)
        raise SyntaxException(http_status=400, message=msg)

