def addFeatureResources(feature_resources):
    db = current.db
    s3db = current.s3db
    config = GIS.get_config()
    ftable = s3db.gis_layer_feature
    ltable = s3db.gis_layer_config
    layers_feature_resource = []
    append = layers_feature_resource.append
    for layer in feature_resources:
        name = str(layer['name'])
        _layer = dict(name=name)
        id = str(layer['id'])
        id = re.sub('\\W', '_', id)
        _layer['id'] = id
        layer_id = layer.get('layer_id', None)
        if layer_id:
            query = ftable.layer_id == layer_id
            lquery = (ltable.layer_id == layer_id) & (ltable.config_id == config.id)
            left = ltable.on(lquery)
            row = db(query).select(ftable.id, ftable.controller, ftable.function, ftable.filter, ftable.trackable, ftable.use_site, ftable.opacity, ftable.cluster_attribute, ftable.cluster_distance, ftable.cluster_threshold, ftable.dir, ltable.style, left=left, limitby=(0, 1)).first()
            style = layer.get('style', row['gis_layer_config.style'])
            row = row['gis_layer_feature']
            if row.use_site:
                maxdepth = 1
                show_ids = '&show_ids=true'
            else:
                maxdepth = 0
                show_ids = ''
            url = '%s.geojson?layer=%i&components=None&maxdepth=%s%s' % (URL(row.controller, row.function), row.id, maxdepth, show_ids)
            filter = layer.get('filter', row.filter)
            if filter:
                url = '%s&%s' % (url, filter)
            if row.trackable:
                url = '%s&track=1' % url
            opacity = layer.get('opacity', row.opacity)
            cluster_attribute = layer.get('cluster_attribute', row.cluster_attribute)
            cluster_distance = layer.get('cluster_distance', row.cluster_distance)
            cluster_threshold = layer.get('cluster_threshold', row.cluster_threshold)
            dir = layer.get('dir', row.dir)
            if style:
                try:
                    style = json.loads(style)
                except:
                    style = None
            if not style:
                marker = layer.get('marker', Marker(layer_id=layer_id).as_dict())
        else:
            url = layer['url']
            tablename = layer['tablename']
            table = s3db[tablename]
            if 'location_id' in table.fields:
                maxdepth = 0
                show_ids = ''
            elif 'site_id' in table.fields:
                maxdepth = 1
                show_ids = '&show_ids=true'
            else:
                continue
            options = 'components=None&maxdepth=%s%s&label_off=1' % (maxdepth, show_ids)
            if '?' in url:
                url = '%s&%s' % (url, options)
            else:
                url = '%s?%s' % (url, options)
            opacity = layer.get('opacity', 1)
            cluster_attribute = layer.get('cluster_attribute', CLUSTER_ATTRIBUTE)
            cluster_distance = layer.get('cluster_distance', CLUSTER_DISTANCE)
            cluster_threshold = layer.get('cluster_threshold', CLUSTER_THRESHOLD)
            dir = layer.get('dir', None)
            style = layer.get('style', None)
            if style:
                try:
                    style = json.loads(style)
                except:
                    style = None
            if not style:
                marker = layer.get('marker', None)
        if 'active' in layer and (not layer['active']):
            _layer['visibility'] = False
        if opacity != 1:
            _layer['opacity'] = '%.1f' % opacity
        if cluster_attribute != CLUSTER_ATTRIBUTE:
            _layer['cluster_attribute'] = cluster_attribute
        if cluster_distance != CLUSTER_DISTANCE:
            _layer['cluster_distance'] = cluster_distance
        if cluster_threshold != CLUSTER_THRESHOLD:
            _layer['cluster_threshold'] = cluster_threshold
        if dir:
            _layer['dir'] = dir
        if style:
            _layer['style'] = style
        elif marker:
            _layer['marker'] = dict(i=marker['image'], h=marker['height'], w=marker['width'])
        else:
            url = '%s&markers=1' % url
        _layer['url'] = url
        append(_layer)
    return layers_feature_resource

def concretize_compiler_flags(self, spec):
    if not (spec.architecture.platform_os and spec.architecture.target):
        return True
    compiler_match = lambda other: spec.compiler == other.compiler and spec.architecture == other.architecture
    ret = False
    for flag in spack.spec.FlagMap.valid_compiler_flags():
        if flag not in spec.compiler_flags:
            spec.compiler_flags[flag] = list()
        try:
            nearest = next((p for p in spec.traverse(direction='parents') if compiler_match(p) and p is not spec and (flag in p.compiler_flags)))
            nearest_flags = nearest.compiler_flags.get(flag, [])
            flags = spec.compiler_flags.get(flag, [])
            if set(nearest_flags) - set(flags):
                spec.compiler_flags[flag] = list(llnl.util.lang.dedupe(nearest_flags + flags))
                ret = True
        except StopIteration:
            pass
    try:
        compiler = spack.compilers.compiler_for_spec(spec.compiler, spec.architecture)
    except spack.compilers.NoCompilerForSpecError:
        if self.check_for_compiler_existence:
            raise
        return ret
    for flag in compiler.flags:
        config_flags = compiler.flags.get(flag, [])
        flags = spec.compiler_flags.get(flag, [])
        spec.compiler_flags[flag] = list(llnl.util.lang.dedupe(config_flags + flags))
        if set(config_flags) - set(flags):
            ret = True
    return ret

